/*
 * ngx_http_isu_module: answers chosen requests inside nginx and passes every other request
 * on to the location's own content handler (normally proxy_pass to the application).
 *
 *     location = /sample {
 *         isu_handler sample;
 *         proxy_pass http://app;
 *     }
 *
 * A handler returns NGX_DECLINED for any request it does not fully understand; the
 * application then answers it, so declining is always correct and is not an error.
 * A handler that answers must answer exactly as the application would (status, body,
 * Content-Type). Errors inside a handler return NGX_HTTP_INTERNAL_SERVER_ERROR.
 *
 * Handlers run on a worker's event loop: no blocking calls (no DB, no files, no sleep).
 * Memory comes from r->pool, which lives until the request is finalized.
 */

#include <ngx_config.h>
#include <ngx_core.h>
#include <ngx_http.h>


typedef ngx_int_t (*isu_handler_pt)(ngx_http_request_t *r);

typedef struct {
    ngx_str_t       name;
    isu_handler_pt  handler;
} isu_handler_entry_t;

typedef struct {
    ngx_int_t       index;   /* into isu_handlers, -1 for off */
} isu_loc_conf_t;


static ngx_int_t isu_sample(ngx_http_request_t *r);

/* One line per handler; the name is what `isu_handler <name>;` refers to. */
static isu_handler_entry_t  isu_handlers[] = {
    { ngx_string("sample"), isu_sample },
    { ngx_null_string, NULL }
};


static char *isu_handler_directive(ngx_conf_t *cf, ngx_command_t *cmd, void *conf);
static void *isu_create_loc_conf(ngx_conf_t *cf);
static char *isu_merge_loc_conf(ngx_conf_t *cf, void *parent, void *child);
static ngx_int_t isu_init(ngx_conf_t *cf);


static ngx_command_t  isu_commands[] = {

    { ngx_string("isu_handler"),
      NGX_HTTP_MAIN_CONF|NGX_HTTP_SRV_CONF|NGX_HTTP_LOC_CONF|NGX_CONF_TAKE1,
      isu_handler_directive,
      NGX_HTTP_LOC_CONF_OFFSET,
      0,
      NULL },

      ngx_null_command
};


static ngx_http_module_t  isu_module_ctx = {
    NULL,                                  /* preconfiguration */
    isu_init,                              /* postconfiguration */

    NULL,                                  /* create main configuration */
    NULL,                                  /* init main configuration */

    NULL,                                  /* create server configuration */
    NULL,                                  /* merge server configuration */

    isu_create_loc_conf,                   /* create location configuration */
    isu_merge_loc_conf                     /* merge location configuration */
};


ngx_module_t  ngx_http_isu_module = {
    NGX_MODULE_V1,
    &isu_module_ctx,                       /* module context */
    isu_commands,                          /* module directives */
    NGX_HTTP_MODULE,                       /* module type */
    NULL,                                  /* init master */
    NULL,                                  /* init module */
    NULL,                                  /* init process */
    NULL,                                  /* init thread */
    NULL,                                  /* exit thread */
    NULL,                                  /* exit process */
    NULL,                                  /* exit master */
    NGX_MODULE_V1_PADDING
};


/* Helpers for handlers */

/*
 * The next `key=value` pair of r->args, both still percent-encoded. Empty pairs are
 * skipped. Returns NGX_OK for a pair and NGX_DONE at the end.
 */
static ngx_int_t
isu_next_arg(u_char **pos, u_char *last, ngx_str_t *key, ngx_str_t *value)
{
    u_char  *p, *start, *eq;

    p = *pos;

    while (p < last && *p == '&') {
        p++;
    }

    if (p == last) {
        return NGX_DONE;
    }

    start = p;
    eq = NULL;

    while (p < last && *p != '&') {
        if (*p == '=' && eq == NULL) {
            eq = p;
        }
        p++;
    }

    key->data = start;
    key->len = (eq ? eq : p) - start;
    value->data = eq ? eq + 1 : p;
    value->len = eq ? (size_t) (p - eq - 1) : 0;

    *pos = p;

    return NGX_OK;
}


/*
 * Decodes a form value ('+' is a space, %XX a byte) into r->pool and checks that it is
 * UTF-8. Returns NGX_DECLINED for a malformed %-escape or invalid UTF-8, so the
 * application decides what such input means.
 */
static ngx_int_t
isu_decode_form_value(ngx_http_request_t *r, ngx_str_t *src, ngx_str_t *dst)
{
    u_char    *s, *d, *end, *p;
    uint32_t   u;
    ngx_int_t  hi, lo;

    dst->data = ngx_pnalloc(r->pool, src->len + 1);
    if (dst->data == NULL) {
        return NGX_ERROR;
    }

    s = src->data;
    end = s + src->len;
    d = dst->data;

    while (s < end) {
        if (*s == '+') {
            *d++ = ' ';
            s++;

        } else if (*s == '%') {
            if (end - s < 3) {
                return NGX_DECLINED;
            }

            hi = ngx_hextoi(s + 1, 1);
            lo = ngx_hextoi(s + 2, 1);

            if (hi == NGX_ERROR || lo == NGX_ERROR) {
                return NGX_DECLINED;
            }

            *d++ = (u_char) (hi * 16 + lo);
            s += 3;

        } else {
            *d++ = *s++;
        }
    }

    dst->len = d - dst->data;

    p = dst->data;
    end = p + dst->len;

    while (p < end) {
        if (*p < 0x80) {
            p++;
            continue;
        }

        u = ngx_utf8_decode(&p, end - p);

        if (u > 0x10ffff || (u >= 0xd800 && u <= 0xdfff)) {
            return NGX_DECLINED;
        }
    }

    return NGX_OK;
}


/*
 * Length of src as the inside of a JSON string, escaped as serde_json does: '"', '\\',
 * the short forms \b \f \n \r \t, other bytes below 0x20 as \u00xx in lowercase hex.
 * ngx_escape_json() is not used because it writes uppercase hex.
 */
static size_t
isu_json_escaped_len(ngx_str_t *src)
{
    size_t   len;
    u_char  *p, *end;

    len = 0;
    end = src->data + src->len;

    for (p = src->data; p < end; p++) {
        if (*p == '"' || *p == '\\' || *p == '\b' || *p == '\f' || *p == '\n'
            || *p == '\r' || *p == '\t')
        {
            len += 2;

        } else if (*p < 0x20) {
            len += sizeof("\\u0000") - 1;

        } else {
            len++;
        }
    }

    return len;
}


static u_char *
isu_json_escape(u_char *dst, ngx_str_t *src)
{
    static u_char   hex[] = "0123456789abcdef";
    u_char         *p, *end;

    end = src->data + src->len;

    for (p = src->data; p < end; p++) {
        switch (*p) {
        case '"':  *dst++ = '\\'; *dst++ = '"'; break;
        case '\\': *dst++ = '\\'; *dst++ = '\\'; break;
        case '\b': *dst++ = '\\'; *dst++ = 'b'; break;
        case '\f': *dst++ = '\\'; *dst++ = 'f'; break;
        case '\n': *dst++ = '\\'; *dst++ = 'n'; break;
        case '\r': *dst++ = '\\'; *dst++ = 'r'; break;
        case '\t': *dst++ = '\\'; *dst++ = 't'; break;

        default:
            if (*p < 0x20) {
                dst = ngx_cpymem(dst, "\\u00", sizeof("\\u00") - 1);
                *dst++ = hex[*p >> 4];
                *dst++ = hex[*p & 0xf];

            } else {
                *dst++ = *p;
            }
        }
    }

    return dst;
}


/*
 * Sends body (allocated from r->pool) as the whole response. The request body, if any, is
 * discarded first so the connection can be kept alive. Returns what the handler returns.
 */
static ngx_int_t
isu_send(ngx_http_request_t *r, ngx_uint_t status, ngx_str_t *content_type,
    u_char *body, size_t len)
{
    ngx_int_t     rc;
    ngx_buf_t    *b;
    ngx_chain_t   out;

    rc = ngx_http_discard_request_body(r);

    if (rc != NGX_OK) {
        return rc;
    }

    r->headers_out.status = status;
    r->headers_out.content_length_n = len;
    r->headers_out.content_type = *content_type;
    r->headers_out.content_type_len = content_type->len;
    r->headers_out.content_type_lowcase = NULL;

    if (len == 0) {
        r->header_only = 1;
    }

    rc = ngx_http_send_header(r);

    if (rc == NGX_ERROR || rc > NGX_OK || r->header_only) {
        return rc;
    }

    b = ngx_calloc_buf(r->pool);
    if (b == NULL) {
        return NGX_ERROR;
    }

    b->pos = body;
    b->last = body + len;
    b->memory = 1;
    b->last_buf = (r == r->main) ? 1 : 0;
    b->last_in_chain = 1;

    out.buf = b;
    out.next = NULL;

    return ngx_http_output_filter(r, &out);
}


/* Handlers */

/*
 * sample: GET or HEAD whose query is exactly one `id` (1 to 18 digits, no leading zero) and
 * at most one `name` (UTF-8 text), in any order, answers
 *
 *     200 application/json  {"id":<id>,"name":"<name>"}     ("" when name is absent)
 *
 * Everything else is declined: other methods, unknown, repeated or encoded keys, a bad id,
 * a malformed name. The application answers those (for example with 400).
 */
static ngx_int_t
isu_sample(ngx_http_request_t *r)
{
    static ngx_str_t  json = ngx_string("application/json");

    u_char     *p, *last, *body, *b;
    size_t      len, i;
    ngx_str_t   key, value, id, raw_name, name;
    ngx_int_t   rc;
    ngx_uint_t  has_id, has_name;

    if (!(r->method & (NGX_HTTP_GET|NGX_HTTP_HEAD))) {
        return NGX_DECLINED;
    }

    has_id = 0;
    has_name = 0;
    ngx_str_null(&id);
    ngx_str_null(&raw_name);

    p = r->args.data;
    last = p + r->args.len;

    while (isu_next_arg(&p, last, &key, &value) == NGX_OK) {

        if (key.len == 2 && ngx_strncmp(key.data, "id", 2) == 0 && !has_id) {
            id = value;
            has_id = 1;

        } else if (key.len == 4 && ngx_strncmp(key.data, "name", 4) == 0 && !has_name) {
            raw_name = value;
            has_name = 1;

        } else {
            return NGX_DECLINED;
        }
    }

    if (!has_id || id.len == 0 || id.len > 18 || id.data[0] == '0') {
        return NGX_DECLINED;
    }

    for (i = 0; i < id.len; i++) {
        if (id.data[i] < '0' || id.data[i] > '9') {
            return NGX_DECLINED;
        }
    }

    rc = isu_decode_form_value(r, &raw_name, &name);

    if (rc != NGX_OK) {
        return rc == NGX_DECLINED ? NGX_DECLINED : NGX_HTTP_INTERNAL_SERVER_ERROR;
    }

    len = sizeof("{\"id\":,\"name\":\"\"}") - 1 + id.len + isu_json_escaped_len(&name);

    body = ngx_pnalloc(r->pool, len);
    if (body == NULL) {
        return NGX_HTTP_INTERNAL_SERVER_ERROR;
    }

    b = ngx_cpymem(body, "{\"id\":", sizeof("{\"id\":") - 1);
    b = ngx_cpymem(b, id.data, id.len);
    b = ngx_cpymem(b, ",\"name\":\"", sizeof(",\"name\":\"") - 1);
    b = isu_json_escape(b, &name);
    b = ngx_cpymem(b, "\"}", sizeof("\"}") - 1);

    return isu_send(r, NGX_HTTP_OK, &json, body, b - body);
}


/* Wiring */

static ngx_int_t
isu_phase_handler(ngx_http_request_t *r)
{
    ngx_int_t        rc;
    isu_loc_conf_t  *ilcf;

    ilcf = ngx_http_get_module_loc_conf(r, ngx_http_isu_module);

    if (ilcf->index < 0 || r != r->main) {
        return NGX_DECLINED;
    }

    rc = isu_handlers[ilcf->index].handler(r);

    if (rc == NGX_DECLINED) {
        return NGX_DECLINED;
    }

    /* Answered (or failed): finish here so the location's proxy_pass never runs. */
    ngx_http_finalize_request(r, rc);

    return NGX_DONE;
}


static char *
isu_handler_directive(ngx_conf_t *cf, ngx_command_t *cmd, void *conf)
{
    isu_loc_conf_t  *ilcf = conf;

    ngx_str_t   *value;
    ngx_uint_t   i;

    if (ilcf->index != NGX_CONF_UNSET) {
        return "is duplicate";
    }

    value = cf->args->elts;

    if (ngx_strcmp(value[1].data, "off") == 0) {
        ilcf->index = -1;
        return NGX_CONF_OK;
    }

    for (i = 0; isu_handlers[i].handler; i++) {
        if (isu_handlers[i].name.len == value[1].len
            && ngx_strncmp(isu_handlers[i].name.data, value[1].data, value[1].len) == 0)
        {
            ilcf->index = i;
            return NGX_CONF_OK;
        }
    }

    ngx_conf_log_error(NGX_LOG_EMERG, cf, 0, "unknown isu_handler \"%V\"", &value[1]);

    return NGX_CONF_ERROR;
}


static void *
isu_create_loc_conf(ngx_conf_t *cf)
{
    isu_loc_conf_t  *conf;

    conf = ngx_pcalloc(cf->pool, sizeof(isu_loc_conf_t));
    if (conf == NULL) {
        return NULL;
    }

    conf->index = NGX_CONF_UNSET;

    return conf;
}


static char *
isu_merge_loc_conf(ngx_conf_t *cf, void *parent, void *child)
{
    isu_loc_conf_t  *prev = parent;
    isu_loc_conf_t  *conf = child;

    ngx_conf_merge_value(conf->index, prev->index, -1);

    return NGX_CONF_OK;
}


static ngx_int_t
isu_init(ngx_conf_t *cf)
{
    ngx_http_handler_pt        *h;
    ngx_http_core_main_conf_t  *cmcf;

    cmcf = ngx_http_conf_get_module_main_conf(cf, ngx_http_core_module);

    h = ngx_array_push(&cmcf->phases[NGX_HTTP_PRECONTENT_PHASE].handlers);
    if (h == NULL) {
        return NGX_ERROR;
    }

    *h = isu_phase_handler;

    return NGX_OK;
}

