"""Stand-in for the application in `make nginx-cmodule-check`: the sample handler's spec.

It answers /sample and /sample-off as the Rust application would, including the requests the
module declines (400, 405). With APP_UPSTREAM set the check uses the real application instead.
Usage: app.py PORT
"""
import json
import re
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, urlsplit

ID = re.compile(r'[1-9][0-9]{0,17}')


def sample(method, query):
    if method not in ('GET', 'HEAD'):
        return 405, {'error': 'method not allowed'}
    try:
        pairs = parse_qsl(query, keep_blank_values=True, errors='strict')
    except (UnicodeDecodeError, ValueError):
        return 400, {'error': 'bad query'}
    keys = [key for key, _ in pairs]
    values = dict(pairs)
    if len(keys) != len(set(keys)) or not set(keys) <= {'id', 'name'} or not ID.fullmatch(values.get('id', '')):
        return 400, {'error': 'bad query'}
    return 200, {'id': int(values['id']), 'name': values.get('name', '')}


class Handler(BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'

    def handle_any(self):
        length = int(self.headers.get('Content-Length') or 0)
        if length:
            self.rfile.read(length)
        url = urlsplit(self.path)
        if url.path in ('/sample', '/sample-off'):
            status, value = sample(self.command, url.query)
        else:
            status, value = 404, {'error': 'not found'}
        body = json.dumps(value, ensure_ascii=False, separators=(',', ':')).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        if self.command != 'HEAD':
            self.wfile.write(body)

    do_GET = do_HEAD = do_POST = do_PUT = do_DELETE = handle_any

    def log_message(self, *args):
        pass


if __name__ == '__main__':
    ThreadingHTTPServer(('127.0.0.1', int(sys.argv[1])), Handler).serve_forever()

