    proxy_set_header Connection "";
    proxy_set_header Host \$host;
    add_header X-Upstream \$upstream_addr always;

    location / {
        proxy_pass http://app;
    }
}
EOF
nginx -t -q
nginx
echo "nginx running, workers: $(workers)"

step "equivalence with the application (${upstream})"
python3 /check/probe.py compare "${cases}" "${with_module}" "${app_only}" || fail "equivalence"

step "concurrent keep-alive clients on 4 workers"
python3 /check/probe.py load "${cases}" "${with_module}" "${app_only}" || fail "concurrent responses"

step "client disconnects"
before=$(workers)
python3 /check/probe.py disconnect "${with_module}" "${cases}"
after=$(workers)
[[ "${before}" == "${after}" ]] && echo "ok   same workers: ${after}" || fail "workers changed: ${before} -> ${after}"
expect_by c "after the disconnects"

step "reload (configuration only)"
nginx -s reload
sleep 0.5
python3 /check/probe.py compare "${cases}" "${with_module}" "${app_only}" >/dev/null || fail "equivalence after reload"
echo "ok   equivalence after reload, workers: $(workers)"

step "module update: a build whose handlers all decline"
original=$(digest)
rm -rf /tmp/declining && cp -a "${module}" /tmp/declining
sed -i 's/if (ilcf->index < 0 || r != r->main) {/if (ilcf->index >= -1 || r != r->main) {/' \
  /tmp/declining/ngx_http_isu_module.c
grep -q 'index >= -1' /tmp/declining/ngx_http_isu_module.c || { echo "could not derive the declining build" >&2; exit 1; }
build /tmp/declining
declining=$(digest)
nginx -s reload
sleep 0.5
echo "observed after reload: answered by $(answered_by) (reload keeps the loaded module)"
restart
expect_by app "after restart (the new module is loaded)"

step "rollback: the original module again"
build "${module}"
restart
expect_by c "after rebuild and restart"
python3 /check/probe.py compare "${cases}" "${with_module}" "${app_only}" >/dev/null || fail "equivalence after rollback"
echo "ok   equivalence after rollback"

step "a build that does not compile"
original=$(digest)
rm -rf /tmp/broken && cp -a "${module}" /tmp/broken
echo '#error broken on purpose' >>/tmp/broken/ngx_http_isu_module.c
if build /tmp/broken >/dev/null 2>&1; then fail "the broken build succeeded"; else echo "ok   build.sh failed"; fi
[[ "$(digest)" == "${original}" ]] && echo "ok   installed module unchanged" || fail "installed module changed"
expect_by c "with the running nginx"

step "a module that fails nginx -t"
echo 'server { listen 127.0.0.1:8099; location / { isu_handler no_such_handler; } }' >/etc/nginx/conf.d/zz-bad.conf
if build /tmp/declining >/dev/null 2>&1; then fail "build.sh accepted a failing nginx -t"; else echo "ok   build.sh failed"; fi
[[ "$(digest)" == "${original}" && "${original}" != "${declining}" ]] &&
  echo "ok   previous module restored" || fail "module after the failed nginx -t: $(digest), expected ${original}"
rm -f /etc/nginx/conf.d/zz-bad.conf
nginx -t -q && echo "ok   nginx -t passes again"
expect_by c "with the running nginx"

step "error log"
if grep -E '\[(alert|crit|emerg)\]|exited on signal' /var/log/nginx/error.log; then
  fail "alerts in the error log"
else
  echo "ok   no alert, crit, emerg or crashed worker"
fi

step "result"
if [[ "${failures}" -eq 0 ]]; then echo "PASS"; else echo "FAIL (${failures})"; exit 1; fi

